package tracebaseline

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"
)

// RenderHTML writes a standalone, diagram-first baseline report.
func RenderHTML(writer io.Writer, suite SuiteReport) error {
	encoded, marshalErr := json.Marshal(suite)
	if marshalErr != nil {
		return fmt.Errorf("cannot encode baseline suite for HTML: %w", marshalErr)
	}
	document := strings.Replace(baselineHTML, "__SUITE_JSON__", string(encoded), 1)
	if _, writeErr := io.WriteString(writer, document); writeErr != nil {
		return fmt.Errorf("cannot write baseline HTML report: %w", writeErr)
	}
	return nil
}

const baselineHTML = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>BanyanDB — One-shard ordinary merge baseline</title>
<style>
:root{--ink:#071016;--panel:#0c1920;--panel2:#10232b;--grid:#17333c;--paper:#dce8df;--muted:#82a19c;--green:#9cff57;--amber:#ffbf45;--red:#ff6262;--cyan:#60d8e8;--line:#2b4b52}
*{box-sizing:border-box}html{background:var(--ink);color:var(--paper);font-family:"IBM Plex Mono","Cascadia Mono",monospace}body{margin:0;background:radial-gradient(circle at 75% 0,#16353a80,transparent 35%),linear-gradient(#ffffff05 1px,transparent 1px),linear-gradient(90deg,#ffffff05 1px,transparent 1px);background-size:auto,28px 28px,28px 28px}.shell{max-width:1460px;margin:auto;padding:28px 32px 72px}.mast{display:grid;grid-template-columns:1fr auto;gap:24px;align-items:end;border-bottom:1px solid var(--line);padding-bottom:22px}.eyebrow,.tag{color:var(--green);letter-spacing:.16em;font-size:11px;text-transform:uppercase}.mast h1{font-family:"Iowan Old Style","Palatino Linotype",serif;font-weight:400;font-size:clamp(42px,6vw,88px);line-height:.86;letter-spacing:-.05em;margin:12px 0 0;max-width:920px}.stamp{width:178px;height:178px;border:1px solid var(--green);border-radius:50%;display:grid;place-content:center;text-align:center;color:var(--green);transform:rotate(5deg);box-shadow:0 0 40px #9cff5718}.stamp b{font-size:38px}.stamp span{font-size:10px;letter-spacing:.12em}.warning{margin:16px 0 26px;border-left:3px solid var(--amber);padding:10px 14px;background:#ffbf450b;color:#d8c699;font-size:12px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px}.card{background:linear-gradient(145deg,#10232bee,#0a171dee);border:1px solid var(--line);padding:18px;position:relative;overflow:hidden}.card:before{content:attr(data-index);position:absolute;right:11px;top:8px;color:#ffffff1c;font-size:42px;font-family:serif}.span12{grid-column:span 12}.span8{grid-column:span 8}.span7{grid-column:span 7}.span6{grid-column:span 6}.span5{grid-column:span 5}.span4{grid-column:span 4}.section-title{display:flex;align-items:baseline;gap:12px;margin-bottom:16px}.section-title h2{font:400 25px "Iowan Old Style",serif;margin:0}.section-title small{color:var(--muted)}svg{width:100%;display:block;overflow:visible}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:1px;background:var(--line);border:1px solid var(--line);margin:18px 0}.kpi{background:var(--panel);padding:16px}.kpi label{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.1em}.kpi strong{font:400 31px "Iowan Old Style",serif;display:block;margin-top:8px}.kpi em{font-style:normal;font-size:10px;color:var(--green)}.legend{display:flex;gap:18px;font-size:10px;color:var(--muted);margin-top:10px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:6px}.gate-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.gate{border:1px solid var(--line);padding:11px;min-height:88px}.gate.pass{border-color:#579b43}.gate.fail{border-color:#8e4848}.gate b{display:block;font-size:11px}.gate span{display:block;color:var(--muted);font-size:9px;margin-top:8px;line-height:1.5}.gate i{float:right;width:9px;height:9px;border-radius:50%;background:var(--red);box-shadow:0 0 10px var(--red)}.gate.pass i{background:var(--green);box-shadow:0 0 10px var(--green)}table{width:100%;border-collapse:collapse;font-size:10px}th,td{text-align:left;padding:8px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-weight:400}.foot{display:flex;justify-content:space-between;margin-top:28px;color:var(--muted);font-size:10px}.axis{stroke:#48636a;stroke-width:1}.gridline{stroke:#1c3941;stroke-width:1}.label{fill:#88a7a2;font:9px monospace}.value{fill:#dce8df;font:11px monospace}.green{stroke:var(--green);fill:none}.amber{stroke:var(--amber);fill:none}.cyan{stroke:var(--cyan);fill:none}.area{fill:#60d8e818;stroke:var(--cyan)}@media(max-width:1050px){.kpis{grid-template-columns:repeat(3,1fr)}}@media(max-width:900px){.span8,.span7,.span6,.span5,.span4{grid-column:span 12}.kpis{grid-template-columns:1fr 1fr}.gate-grid{grid-template-columns:1fr 1fr}.stamp{display:none}.shell{padding:20px 14px}.mast h1{font-size:48px}}
</style></head><body><main class="shell">
<header class="mast"><div><div class="eyebrow">Apache SkyWalking BanyanDB · performance dossier 05</div><h1>ONE SHARD /<br>ORDINARY MERGE</h1></div><div class="stamp"><span>BASELINE</span><b id="stamp-result">—</b><span>PIPELINE DISABLED</span></div></header>
<div class="warning">Interpretation boundary — every measurement describes one active trace shard. It is not whole-node or cluster capacity.</div>
<section class="kpis" id="kpis"></section>
<div class="grid">
<article class="card span7" data-index="01"><div class="section-title"><h2>Acceleration envelope</h2><small>logical time ÷ wall time</small></div><svg id="sweep-diagram" viewBox="0 0 760 270" aria-label="rate sweep diagram"></svg><div class="legend"><span><i class="dot" style="background:var(--green)"></i>sustainable</span><span><i class="dot" style="background:var(--red)"></i>rejected</span><span><i class="dot" style="background:var(--amber)"></i>frozen at 70%</span></div></article>
<article class="card span5" data-index="02"><div class="section-title"><h2>Work-flow ledger</h2><small>core + both SIDX children</small></div><svg id="flow-diagram" viewBox="0 0 520 270" aria-label="merge byte flow diagram"></svg></article>
<article class="card span8" data-index="03"><div class="section-title"><h2>Run-to-run signal</h2><small>five fresh processes after warm-up</small></div><svg id="variance-diagram" viewBox="0 0 860 470" aria-label="run variance dot plot"></svg></article>
<article class="card span4" data-index="04"><div class="section-title"><h2>Selection states</h2><small>timestamp-derived maturity</small></div><svg id="class-diagram" viewBox="0 0 400 330" aria-label="hot and mature merge diagram"></svg></article>
<article class="card span12" data-index="05"><div class="section-title"><h2>Backlog waveform</h2><small>parts in inventory across the accelerated day</small></div><svg id="backlog-diagram" viewBox="0 0 1200 300" aria-label="merge backlog area chart"></svg></article>
<article class="card span12" data-index="06"><div class="section-title"><h2>Correctness circuit</h2><small>results are rejected when a required gate opens</small></div><div class="gate-grid" id="gates"></div></article>
<article class="card span12" data-index="07"><div class="section-title"><h2>Measured runs</h2><small>absolute one-shard values</small></div><table><thead><tr><th>RUN</th><th>MODE</th><th>PRIMARY</th><th>COOLDOWN</th><th>CPU</th><th>PEAK RSS</th><th>READ / WRITE</th><th>HOT / MATURE</th><th>ROW COUNTS</th></tr></thead><tbody id="run-table"></tbody></table><div class="legend">Profile artifacts: each run directory contains primary/cooldown CPU, heap, allocs, block, mutex, and merge-events JSONL files.</div></article>
</div><footer class="foot"><span id="identity"></span><span>Standalone HTML · source data embedded below</span></footer>
<script type="application/json" id="suite-data">__SUITE_JSON__</script>
<script>
const d=JSON.parse(document.getElementById('suite-data').textContent), runs=[...(d.serialRuns||[]),...(d.throughputRuns||[])];
const ns=n=>n/1e9, mb=n=>n/1048576, fmt=(n,p=1)=>Number(n||0).toFixed(p), med=a=>{a=[...a].sort((x,y)=>x-y);return a.length?a[Math.floor(a.length/2)]:0}, q=(a,p)=>{a=[...a].sort((x,y)=>x-y);return a.length?a[Math.min(a.length-1,Math.ceil(a.length*p)-1)]:0};
const tp=d.throughputRuns||[],walls=tp.map(r=>ns(r.primary.wallNanos)),cpus=tp.map(r=>ns((r.primary.end.cpuNanos||0)-(r.primary.start.cpuNanos||0))),rss=tp.map(r=>mb(r.primary.end.rssBytes||0)),allocs=tp.map(r=>mb((r.primary.end.allocatedBytes||0)-(r.primary.start.allocatedBytes||0))),writes=tp.map(r=>mb((r.primary.end.writeBytes||0)-(r.primary.start.writeBytes||0))),firstRun=tp[0]||runs[0]||{},mergeOutput=(firstRun.merges?.aggregates||[]).reduce((sum,aggregate)=>sum+(aggregate.outputBytes||0)+(aggregate.childOutputBytes||0),0),logicalWA=mergeOutput/Math.max(1,d.fixtureInputBytes||firstRun.primary?.inputBytes||0);
const allCorrect=runs.length>0&&runs.every(r=>r.correct),coverageRuns=tp.length?tp:runs,totalHot=coverageRuns.reduce((s,r)=>s+(r.hotMerges||0),0),totalMature=coverageRuns.reduce((s,r)=>s+(r.matureMerges||0),0);
document.getElementById('stamp-result').textContent='HOLD';
document.getElementById('kpis').innerHTML=[['FROZEN RATE',fmt(d.frozenAcceleration,0)+'×','70% of Amax'],['PRIMARY MEDIAN',fmt(med(walls),2)+'s','p95 '+fmt(q(walls,.95),2)+'s'],['CPU MEDIAN',fmt(med(cpus),2)+'s',fmt(med(cpus)/Math.max(.001,med(walls)),2)+' effective cores'],['PEAK RSS',fmt(q(rss,.95),1)+' MiB','p95 across runs'],['LOGICAL WA',fmt(logicalWA,2)+'×','core + SIDX merge output'],['MERGE COVERAGE',totalHot+' / '+totalMature,'hot / mature']].map(x=>'<div class="kpi"><label>'+x[0]+'</label><strong>'+x[1]+'</strong><em>'+x[2]+'</em></div>').join('');
function line(x1,y1,x2,y2,c='gridline'){return '<line class="'+c+'" x1="'+x1+'" y1="'+y1+'" x2="'+x2+'" y2="'+y2+'"/>'} function text(x,y,s,c='label',a='start'){return '<text class="'+c+'" x="'+x+'" y="'+y+'" text-anchor="'+a+'">'+s+'</text>'}
{const s=d.sweep||[],svg=document.getElementById('sweep-diagram'),mx=Math.max(1,...s.map(x=>x.acceleration)),my=Math.max(1,...s.map(x=>ns(x.drainNanos)),...s.map(x=>ns(x.p95LagNanos)));let h='';for(let i=0;i<5;i++){let y=225-i*45;h+=line(55,y,730,y)+text(45,y+3,fmt(my*i/4,1),'label','end')}let pts=s.map((p,i)=>{let x=65+(p.acceleration/mx)*640,y=225-(ns(p.drainNanos)/my)*180;h+='<circle cx="'+x+'" cy="'+y+'" r="7" fill="'+(p.sustainable?'#9cff57':'#ff6262')+'"/>'+text(x,y-14,fmt(p.acceleration,0)+'×','value','middle');return x+','+y}).join(' ');h+='<polyline points="'+pts+'" class="green" stroke-width="2"/>';let fx=65+(d.frozenAcceleration/mx)*640;h+=line(fx,35,fx,235,'amber')+text(fx,26,'FROZEN','value','middle');svg.innerHTML=h}
{const inv=firstRun.inventory||{},input=d.fixtureInputBytes||firstRun.primary?.inputBytes||0,final=(inv.coreBytes||0)+Object.values(inv.indexBytes||{}).reduce((a,b)=>a+b,0),vals=[input,mergeOutput,final],names=['FIXTURE IN','COMPACTION OUT','FINAL LEDGER'],mx=Math.max(1,...vals);let h='';vals.forEach((v,i)=>{let x=30+i*170,w=110,hh=40+170*v/mx,y=235-hh;h+='<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+hh+'" fill="'+['#60d8e833','#ffbf4533','#9cff5733'][i]+'" stroke="'+['#60d8e8','#ffbf45','#9cff57'][i]+'"/>'+text(x+w/2,255,names[i],'label','middle')+text(x+w/2,y-10,fmt(mb(v),1)+' MiB','value','middle');if(i<2)h+='<path d="M '+(x+w)+' '+(y+hh/2)+' C '+(x+145)+' '+(y+hh/2)+', '+(x+145)+' 135, '+(x+170)+' 135" stroke="#48636a" fill="none"/>'});document.getElementById('flow-diagram').innerHTML=h}
{let metrics=[['WALL s',walls],['CPU s',cpus],['RSS MiB',rss],['ALLOC MiB',allocs],['WRITE MiB',writes]],h='';metrics.forEach((m,row)=>{let y=55+row*88,a=m[1],mx=Math.max(1,...a);h+=text(20,y,m[0],'value');h+=line(145,y,820,y,'axis');a.forEach((v,i)=>{let x=145+v/mx*640;h+='<circle cx="'+x+'" cy="'+(y+(i%3-1)*8)+'" r="6" fill="#60d8e8"/>'});let md=med(a),p=q(a,.95);h+=line(145+md/mx*640,y-22,145+md/mx*640,y+22,'green')+line(145+p/mx*640,y-22,145+p/mx*640,y+22,'amber')+text(820,y-14,'med '+fmt(md,2)+' · p95 '+fmt(p,2),'label','end')});document.getElementById('variance-diagram').innerHTML=h}
{let total=Math.max(1,totalHot+totalMature),hot=totalHot/total,rad=105,cx=200,cy=150,circ=2*Math.PI*rad;document.getElementById('class-diagram').innerHTML='<circle cx="'+cx+'" cy="'+cy+'" r="'+rad+'" fill="none" stroke="#17333c" stroke-width="28"/><circle cx="'+cx+'" cy="'+cy+'" r="'+rad+'" fill="none" stroke="#60d8e8" stroke-width="28" stroke-dasharray="'+(circ*hot)+' '+circ+'" transform="rotate(-90 '+cx+' '+cy+')"/><circle cx="'+cx+'" cy="'+cy+'" r="'+rad+'" fill="none" stroke="#9cff57" stroke-width="28" stroke-dasharray="'+(circ*(1-hot))+' '+circ+'" stroke-dashoffset="'+(-circ*hot)+'" transform="rotate(-90 '+cx+' '+cy+')"/>'+text(cx,145,totalHot,'value','middle')+text(cx,162,'HOT','label','middle')+text(75,300,'grace-tail · '+totalHot,'label')+text(325,300,'mature · '+totalMature,'label','end')}
{const st=(tp[0]||runs[0]||{}).status||[],mx=Math.max(1,...st.map(x=>x.coreParts||0));let pts=st.map((p,i)=>(45+i/Math.max(1,st.length-1)*1110)+','+(250-(p.coreParts||0)/mx*205)).join(' '),h='<polygon class="area" points="45,250 '+pts+' 1155,250"/>';for(let i=0;i<5;i++){let y=250-i*50;h+=line(45,y,1155,y)+text(35,y+3,fmt(mx*i/4,0),'label','end')}h+=text(45,280,'00:00 LOGICAL','label')+text(1155,280,'24:00 + DRAIN','label','end');document.getElementById('backlog-diagram').innerHTML=h}
const gates=[['RESOURCE ENVELOPE',runs.every(r=>r.environment?.gomaxprocs===4&&r.environment?.memoryMax==='8589934592'&&r.environment?.memorySwapMax==='0'&&r.environment?.pidsMax==='512'),'4 pinned CPUs · 8 GiB · swap disabled · 512 PIDs'],['CGROUP ISOLATION',runs.every(r=>r.environment?.dataNodeCgroup&&r.environment?.controllerCgroup&&r.environment.dataNodeCgroup!==r.environment.controllerCgroup),'Writer/controller is outside the measured data-node cgroup'],['ONE SHARD',d.oneShardOnly&&runs.every(r=>r.environment?.oneShardOnly),'No whole-node capacity inference'],['ROW COUNTS',allCorrect,'Core, latency, and start_time row totals reconcile'],['LOGICAL LEDGER',d.ledgerVerified,'Content and keys reconcile independent of physical layout'],['NO SAMPLING',runs.every(r=>(r.samplingCalls||0)===0),'Pipeline disabled and zero Decide calls'],['HOT COVERAGE',tp.every(r=>(r.hotMerges||0)>=10),'At least ten grace-tail selections in every throughput run'],['MATURE COVERAGE',tp.every(r=>(r.matureMerges||0)>=10),'At least ten mature selections in every throughput run'],['REPETITIONS',tp.length>=5,'Five comparable fresh throughput processes'],['PRE-ROLL',d.preRollDiscovered,'Natural mature opening selection discovered']],overallReady=gates.every(g=>g[1]);document.getElementById('stamp-result').textContent=overallReady?'VALID':'HOLD';document.getElementById('gates').innerHTML=gates.map(g=>'<div class="gate '+(g[1]?'pass':'fail')+'"><i></i><b>'+g[0]+'</b><span>'+g[2]+'</span></div>').join('');
document.getElementById('run-table').innerHTML=runs.map(r=>{let cpu=ns((r.primary?.end?.cpuNanos||0)-(r.primary?.start?.cpuNanos||0)),rw=fmt(mb((r.primary?.end?.readBytes||0)-(r.primary?.start?.readBytes||0)),1)+' / '+fmt(mb((r.primary?.end?.writeBytes||0)-(r.primary?.start?.writeBytes||0)),1);return '<tr><td>'+r.runID+'</td><td>'+r.mode+'</td><td>'+fmt(ns(r.primary?.wallNanos),2)+'s</td><td>'+fmt(ns(r.cooldown?.wallNanos),3)+'s</td><td>'+fmt(cpu,2)+'s</td><td>'+fmt(mb(r.primary?.end?.rssBytes),1)+' MiB</td><td>'+rw+'</td><td>'+r.hotMerges+' / '+r.matureMerges+'</td><td style="color:'+(r.correct?'var(--green)':'var(--red)')+'">'+(r.correct?'PASS':'FAIL')+'</td></tr>'}).join('');document.getElementById('identity').textContent='commit '+(d.commit||'unknown')+' · binary '+(d.binarySHA256||'unrecorded').slice(0,12)+' · generated '+(d.generatedAt||'');
</script></main></body></html>`
